{
  "findings": [
    {
      "check_id": "CKV_AZURE_114",
      "title": "Key Vault secret has no content type",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The secret lacks content type metadata, making it harder for consumers and governance processes to identify and handle the connection string appropriately."
    },
    {
      "check_id": "CKV_AZURE_41",
      "title": "Key Vault secret has no expiration date",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The database connection string has no expiration date, allowing the embedded credentials to remain valid indefinitely if rotation is not otherwise enforced."
    }
  ],
  "patched_code": "variable \"database_connection_string_expiration_date\" {\n  description = \"Expiration date for the database connection string secret in RFC3339 format.\"\n  type        = string\n}\n\nresource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name            = \"database-connection-string\"\n  value           = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id    = azurerm_key_vault.legal_keyvault.id\n  content_type    = \"text/plain; charset=utf-8\"\n  expiration_date = var.database_connection_string_expiration_date\n  depends_on      = [azurerm_mssql_database.legal_metadata_db]\n}\n",
  "fix_summary": "Added content type metadata and a required, configurable RFC3339 expiration date for the Key Vault secret."
}
